// ===== Figure (2): current vs time graph =====
// Axes origin
let ax_x = 6.0
let ax_y = 0
let T = 4.0

// I axis (vertical)
line((ax_x, ax_y - 2.8), (ax_x, ax_y + 2.8), stroke: 1.5pt + black, mark: (end: ">"))
content((ax_x - 0.3, ax_y + 3.0), text(size: 16pt)[$I$])

// t axis (horizontal)
line((ax_x, ax_y), (ax_x + T + 0.8, ax_y), stroke: 1.5pt + black, mark: (end: ">"))
content((ax_x + T + 0.8, ax_y - 0.3), text(size: 16pt)[$t$])

// Origin label
content((ax_x - 0.3, ax_y - 0.4), text(size: 14pt)[$0$])

// T/2 and T labels on time axis
line((ax_x + T/2, ax_y + 0.1), (ax_x + T/2, ax_y - 0.1), stroke: 1pt)
content((ax_x + T/2, ax_y - 0.4), text(size: 14pt)[$T\/2$])
line((ax_x + T, ax_y + 0.1), (ax_x + T, ax_y - 0.1), stroke: 1pt)
content((ax_x + T, ax_y - 0.4), text(size: 14pt)[$T$])

// Piecewise linear: constant positive I0 from 0 to T/2, then linearly decreases to -I0 at T
let I0 = 2.2
// Flat section from 0 to T/2
line((ax_x, ax_y + I0), (ax_x + T/2, ax_y + I0), stroke: 2.2pt + black)
// Diagonal section from T/2 to T
line((ax_x + T/2, ax_y + I0), (ax_x + T, ax_y - I0), stroke: 2.2pt + black)

// I0 label
line((ax_x - 0.1, ax_y + I0), (ax_x + 0.1, ax_y + I0), stroke: 1pt)
content((ax_x - 0.4, ax_y + I0), text(size: 14pt)[$I_0$])

// Caption
content((ax_x + 1.5, ax_y - 3.4), text(size: 16pt)[Figure (2)])

